/**
 * Assets: the stored images, how a task names one, and the slot bindings that say what each
 * one serves. Neither script nor production, since both layers and the store read them.
 */
import type { Transport } from './textmodels.js';

/**
 * Kinds of image assets (report §3, §7). The first five are the output of a planned task. A
 * `concept` is drawn on demand from a sentence, bound to what it sketches and consumed by nothing
 * (`docs/plans/archive/INDEX.md#on-demand-concept-images`). A `reference` is bytes the author brought in
 * from outside: generated by nothing and consumed by construction.
 */
export type AssetKind =
  | 'location_ref'
  | 'portrait'
  | 'model_sheet'
  | 'outfit_sheet'
  | 'shot_image'
  | 'concept'
  | 'reference';

/** A reference to a stored asset by its content hash. */
export interface AssetRef {
  /** sha256 content hash of the asset bytes. */
  hash: string;
  /** File extension without the dot, e.g. `png`. */
  ext: string;
}

/** Image-generation parameters that participate in the dedupe hash. */
export interface ImageParams {
  modelId: string;
  aspect?: string;
  seed?: number;
  /**
   * Extra params, hashed verbatim, so they carry task identity as well as anything a provider
   * reads. No provider reads any today; `sheet` is the key of the staging sheet a member shot is
   * drawn from, which re-keys the shot when the sheet's inputs move.
   */
  extra?: Record<string, string | number | boolean>;
}

/** The entity, scene or shot an asset serves. */
export interface AssetBinding {
  characterId?: string;
  outfit?: string;
  /**
   * Which of an outfit's sheets this is. On a binding written since takes were held; a sheet row
   * without one is told apart from its siblings through its task's inputs instead.
   */
  angle?: string;
  locationId?: string;
  variant?: string;
  sceneId?: string;
  shotId?: string;
}

/**
 * How a take's bytes entered its slot. Stamped on the row by the first hold and kept by every
 * later one, so a restore leaves it alone and records itself on the attempt instead.
 */
export type TakeVia = 'run' | 'graph' | 'adopt' | 'promote' | 'upload' | 'migrated';

/** What a hold stamps on the row it holds. */
export interface TakeStamp {
  /** ISO timestamp of the hold. */
  at?: string;
  via?: TakeVia;
}

/**
 * What the one-shot migration writes onto a row: the take bits, and for a sheet the angle
 * backfilled onto its outfit binding.
 */
export interface TakeEdit extends TakeStamp {
  current: boolean;
  angle?: string;
}

/** A stored, generated image and its provenance (report §3, §8). */
export interface Asset {
  hash: string;
  ext: string;
  kind: AssetKind;
  /** Task hash that produced it. */
  sourceTask: string;
  prompt?: string;
  /** Reference asset hashes fed into the generation, in order. */
  refs: string[];
  /** The model as `project.yaml` or the node named it, never its OpenRouter spelling. */
  modelId: string;
  /**
   * Which key carried the call. Absent on a record written before routing existed, and then
   * read as the model's own vendor.
   */
  transport?: Transport;
  params?: ImageParams;
  /**
   * Everything this asset satisfies, for the manifest index. A list because bytes are keyed by
   * content: two tasks that produce the same image share one record, and the second binding
   * must not erase the first. A manifest written with a single record reads as one element.
   */
  satisfies: AssetBinding[];
  /**
   * Whether these are the bytes the slot holds. At most one row per slot; a hold clears the
   * others in the same write. Absent on a row written before takes were held, which every reader
   * treats as false and `migrateCurrent` stamps once.
   */
  current?: boolean;
  /**
   * Whether a person approved this take. Never cleared by a hold, so a superseded take keeps it
   * as history; a surface asking "is this approved" reads `current` as well.
   */
  accepted: boolean;
  /** ISO timestamp of the last hold — when the slot most recently took these bytes. */
  at?: string;
  /** See {@link TakeVia}. */
  via?: TakeVia;
  /**
   * A short human name, for an asset whose name cannot be derived from what it serves. A plate's
   * binding gives it the name "Café Mori — night"; a concept was asked for in a sentence, and that
   * sentence is its only name.
   */
  title?: string;
}

/**
 * Whether `asset` serves everything `binding` names — one place to ask, so the surfaces don't
 * each spell the list traversal differently. An empty `binding` matches any bound asset.
 */
export function bindsTo(asset: Asset, binding: AssetBinding): boolean {
  const wanted = Object.entries(binding).filter(([, v]) => v !== undefined);
  return asset.satisfies.some((b) => wanted.every(([k, v]) => b[k as keyof AssetBinding] === v));
}
